#!/usr/bin/env node
// Builds the LOCAL hub — versions/index.html — from variants.json.
//
//   node tools/build-hub.mjs      or      npm run hub
//
// Double-click the result. It reads previews off disk and links to the dev
// server, so it works with no network and no build; where a variant is also
// deployed it offers that address as a second link rather than replacing the
// local one. The deployed copy of this same page is generated by deploy.mjs
// from the same template, so the two cannot drift.

import { readFileSync, writeFileSync, mkdirSync, existsSync, cpSync, rmSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { execFileSync } from 'node:child_process';
import { buildHub, previewFor } from './hub.mjs';

const ROOT = resolve(import.meta.dirname, '..');
const REGISTER = JSON.parse(readFileSync(join(ROOT, 'variants.json'), 'utf8'));
const BASE = REGISTER.base.replace(/\/+$/, '') + '/';
const ORIGIN = 'https://sigovs.github.io';

// "Live" here means published, and it is asked of the branch rather than
// assumed: a hub that claims a deploy that is not there sends you to a 404.
//
// The ref is FETCHED first. Reading origin/gh-pages without that reports nothing
// on any clone that has never pulled the branch — which is every clone, because
// nothing else here ever touches it — and the hub then prints "0 deployed" under
// a card whose deploy is live. Wrong in the quiet direction, which is the bad one.
let published = new Set();
try {
  execFileSync('git', ['fetch', '-q', 'origin', 'gh-pages'], {
    cwd: ROOT, stdio: 'ignore', timeout: 25000,
  });
  const ls = execFileSync('git', ['ls-tree', '--name-only', 'FETCH_HEAD'], {
    cwd: ROOT, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'],
  });
  published = new Set(ls.trim().split('\n').map((s) => s.replace(/\/$/, '')));
} catch {
  console.log('  (gh-pages unreadable — deploy status unknown, cards show local only)');
}

const out = join(ROOT, 'versions');
mkdirSync(out, { recursive: true });

// The previews are copied IN rather than linked to with ../. versions/ is then
// self-contained: it serves correctly whether it is opened as a file, served
// from the repo root, or served with versions/ itself as the document root —
// and a ../ that only works under one of those three is the kind of path that
// looks fine until someone zips the folder and sends it.
rmSync(join(out, 'previews'), { recursive: true, force: true });
if (existsSync(join(ROOT, 'previews'))) {
  cpSync(join(ROOT, 'previews'), join(out, 'previews'), { recursive: true });
}

const html = buildHub(REGISTER, {
  mode: 'local',
  root: ROOT,
  isLive: (v) => published.has(v.slug),
  origin: ORIGIN,
  base: BASE,
});

writeFileSync(join(out, 'index.html'), html);

console.log(`\n  versions/index.html  —  ${REGISTER.variants.length} version(s)`);
for (const v of REGISTER.variants) {
  const shot = previewFor(ROOT, v.slug);
  console.log(`    ${v.slug.padEnd(22)} ${shot ? 'preview ok' : 'NO PREVIEW — node tools/shoot.mjs'}`);
}
console.log('');
